func TestGlobalDryRunSkipsAutoRefreshNetworkAndBothStoreTargets(t *testing.T) {
	home := t.TempDir()
	restore, err := cliutil.SetHomeOverride(home)
	if err != nil {
		t.Fatal(err)
	}
	defer restore()
	defaultPath := defaultDBPath("name-that-ui-pp-cli")
	customPath := filepath.Join(t.TempDir(), "custom.db")
	requests := 0
	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		requests++
		t.Errorf("global --dry-run made request %s", r.URL)
	}))
	defer server.Close()
	t.Setenv("NAME_THAT_UI_BASE_URL", server.URL)
	t.Setenv("PRINTING_PRESS_VERIFY", "")

	// The direct helper guard covers an explicitly selected local store as
	// well as the default. It must return before lock creation, migrations,
	// generated refresh, or NameThatUI mirror enrichment.
	for _, path := range []string{defaultPath, customPath} {
		meta := autoRefreshIfStaleAtPath(context.Background(), &rootFlags{dataSource: "auto", dryRun: true}, []string{"catalog", "styles"}, path)
		if meta.Decision != "skipped" || meta.Reason != "dry_run" || meta.Ran {
			t.Fatalf("freshness(%s) = %+v", path, meta)
		}
		if _, err := os.Stat(path); !errors.Is(err, os.ErrNotExist) {
			t.Fatalf("dry run wrote store %s: %v", path, err)
		}
	}

	// Exercise the root PersistentPreRunE path that used to refresh before a
	// command could honor --dry-run.
	cmd := RootCmd()
	cmd.SetOut(&bytes.Buffer{})
	cmd.SetErr(&bytes.Buffer{})
	cmd.SetArgs([]string{"--json", "--no-learn", "--dry-run", "catalog", "list"})
	if err := cmd.Execute(); err != nil {
		t.Fatal(err)
	}
	if requests != 0 {
		t.Fatalf("dry run requests = %d, want 0", requests)
	}
	for _, path := range []string{defaultPath, customPath} {
		if _, err := os.Stat(path); !errors.Is(err, os.ErrNotExist) {
			t.Fatalf("dry run persisted auto-refresh or mirror data at %s: %v", path, err)
		}
	}
}

func TestAutoRefreshUsesCommandSelectedDBPath(t *testing.T) {
	home := t.TempDir()
	restore, err := cliutil.SetHomeOverride(home)
	if err != nil {
		t.Fatalf("set home override: %v", err)
	}
	defer restore()
	defaultPath := defaultDBPath("name-that-ui-pp-cli")
	customPath := filepath.Join(t.TempDir(), "custom.db")
	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if r.URL.Path != "/" {
			http.NotFound(w, r)
			return
		}
		_, _ = w.Write([]byte(`<script type="application/ld+json">{"itemListElement":[{"id":"catalog-1","name":"Button"}]}</script><script>` + nameThatUIPush(`{"entries":[{"slug":"button","platform":"react","name":"Button","api":[],"parts":[]}]}`) + `</script>`))
	}))
	defer server.Close()
	t.Setenv("NAME_THAT_UI_BASE_URL", server.URL)
	t.Setenv("PRINTING_PRESS_VERIFY", "")

	meta := autoRefreshIfStaleAtPath(context.Background(), &rootFlags{dataSource: "auto", timeout: time.Second, rateLimit: 0}, []string{"catalog"}, customPath)
	if meta.Decision == "error" || !meta.Ran || meta.Reason != "refreshed" {
		t.Fatalf("freshness = %+v", meta)
	}
	if _, err := os.Stat(customPath); err != nil {
		t.Fatalf("custom store was not used: %v", err)
	}
	if _, err := os.Stat(defaultPath); !errors.Is(err, os.ErrNotExist) {
		t.Fatalf("unrelated default store was touched: %v", err)
	}
	custom, err := store.Open(customPath)
	if err != nil {
		t.Fatal(err)
	}
	defer custom.Close()
	if rows, err := custom.List("components", 0); err != nil || len(rows) != 1 {
		t.Fatalf("domain mirror was not hydrated in custom store: %d, %v", len(rows), err)
	}
}

func TestRunAutoRefreshPopulatesNameThatUIMirrorAndSnapshots(t *testing.T) {
	calls := map[string]int{}
	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		calls[r.URL.Path]++
		switch r.URL.Path {
		case "/":
			_, _ = w.Write([]byte(`<script type="application/ld+json">{"itemListElement":[{"id":"catalog-1","name":"Button"}]}</script><script>` + nameThatUIPush(`{"entries":[{"slug":"button","platform":"react","name":"Button","api":[],"parts":[]}]}`) + `</script>`))
		case "/styles":
			_, _ = w.Write([]byte(`<script type="application/ld+json">{"@type":"ItemList","itemListElement":[{"id":"style-1","name":"Glass","url":"/styles/glass"}]}</script>`))
		default:
			_, _ = w.Write([]byte("<h1>Style</h1><h2>Accessibility</h2><p>Readable.</p><script>" + nameThatUIPush(`{"signals":[]}`) + "</script>"))
		}
	}))
	defer server.Close()
	t.Setenv("NAME_THAT_UI_BASE_URL", server.URL)
	t.Setenv("PRINTING_PRESS_VERIFY", "")

	db, err := store.OpenWithContext(context.Background(), filepath.Join(t.TempDir(), "data.db"))
	if err != nil {
		t.Fatal(err)
	}
	defer db.Close()
	if err := runAutoRefresh(context.Background(), &rootFlags{timeout: 5 * time.Second, rateLimit: 0}, db, []string{"catalog", "styles"}); err != nil {
		t.Fatalf("runAutoRefresh: %v", err)
	}
	for _, resource := range []string{"components", "style_details", "component_snapshots", "style_snapshots"} {
		rows, err := db.List(resource, 0)
		if err != nil || len(rows) != 1 {
			t.Fatalf("%s rows = %d, err=%v; want one", resource, len(rows), err)
		}
	}
	if calls["/"] != 2 || calls["/styles"] != 2 || calls["/styles/glass"] != 1 {
		t.Fatalf("requests = %#v; want generated plus mirror requests", calls)
	}
}

func TestAutoRefreshLockRecoversStaleLock(t *testing.T) {
	dbPath := filepath.Join(t.TempDir(), "data.db")
	lockPath := dbPath + ".auto-refresh.lock"
	if err := os.WriteFile(lockPath, []byte("crashed-owner\n"), 0o600); err != nil {
		t.Fatal(err)
	}
	staleAt := time.Now().Add(-autoRefreshLockStaleAfter - time.Second)
	if err := os.Chtimes(lockPath, staleAt, staleAt); err != nil {
		t.Fatal(err)
	}
	lock, err := acquireAutoRefreshLock(context.Background(), dbPath)
	if err != nil {
		t.Fatalf("recover stale lock: %v", err)
	}
	lock.Release()
	if _, err := os.Stat(lockPath); !errors.Is(err, os.ErrNotExist) {
		t.Fatalf("lock remains after release: %v", err)
	}
}

