func TestAutoRefreshSerializesConcurrentFreshHome(t *testing.T) {
	var mu sync.Mutex
	calls := map[string]int{}
	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		mu.Lock()
		calls[r.URL.Path]++
		mu.Unlock()
		switch r.URL.Path {
		case "/":
			_, _ = w.Write([]byte(`<script type="application/ld+json">{"itemListElement":[{"id":"catalog-1","name":"Button"}]}</script><script>` + nameThatUIPush(`{"entries":[{"slug":"button","platform":"react","name":"Button","api":[],"parts":[]}]}`) + `</script>`))
		case "/styles":
			_, _ = w.Write([]byte(`<script type="application/ld+json">{"@type":"ItemList","itemListElement":[{"id":"style-1","name":"Glass","url":"/styles/glass"}]}</script>`))
		default:
			_, _ = w.Write([]byte("<h1>Style</h1><h2>Accessibility</h2><p>Readable.</p><script>" + nameThatUIPush(`{"signals":[]}`) + "</script>"))
		}
	}))
	defer server.Close()
	t.Setenv("NAME_THAT_UI_BASE_URL", server.URL)
	t.Setenv("PRINTING_PRESS_VERIFY", "")
	home := t.TempDir()
	restore, err := cliutil.SetHomeOverride(home)
	if err != nil {
		t.Fatal(err)
	}
	defer restore()

	start := make(chan struct{})
	metas := make(chan cliutil.FreshnessMeta, 2)
	for range 2 {
		go func() {
			<-start
			metas <- autoRefreshIfStale(context.Background(), &rootFlags{dataSource: "auto", timeout: 5 * time.Second, rateLimit: 0}, []string{"catalog", "styles"})
		}()
	}
	close(start)
	ran := 0
	for range 2 {
		meta := <-metas
		if meta.Decision == "error" {
			t.Fatalf("auto-refresh failed: %+v", meta)
		}
		if meta.Ran {
			ran++
		}
	}
	if ran != 1 {
		t.Fatalf("refresh runs = %d, want one owner and one re-checking waiter", ran)
	}
	mu.Lock()
	defer mu.Unlock()
	if calls["/"] != 2 || calls["/styles"] != 2 || calls["/styles/glass"] != 1 {
		t.Fatalf("requests = %#v; waiter repeated refresh", calls)
	}
}

func nameThatUIPush(payload string) string {
	encoded, _ := json.Marshal([]any{1, payload})
	return "self.__next_f.push(" + string(encoded) + ")"
}
